from math import log

def landauer(bits: int, temperature: float) -> float:
    if bits < 0 or temperature <= 0:
        raise ValueError("invalid physical parameters")
    return bits * 1.380649e-23 * temperature * log(2.0)

if __name__ == "__main__":
    for n in (1, 1_000, 1_000_000, 1_000_000_000):
        print(n, landauer(n, 300.0))

from math import exp, log

def construct(lower_work: float) -> tuple[list[float], list[float]]:
    upper_work = -log(1.0 - exp(-lower_work))
    return [0.5, 0.5], [lower_work, upper_work]

def audit(p: list[float], w: list[float]) -> tuple[float, float]:
    return sum(pi * exp(-wi) for pi, wi in zip(p, w)), sum(pi * wi for pi, wi in zip(p, w))

if __name__ == "__main__":
    p, w = construct(0.2)
    exponential_average, mean = audit(p, w)
    print("works", w)
    print("Jarzynski average", exponential_average, "target", 0.5)
    print("mean", mean, "Landauer", log(2.0))

from collections import deque
from typing import Iterable, Mapping

def closure(edges: Mapping[str, Iterable[str]], easy: set[str]) -> set[str]:
    pred: dict[str, set[str]] = {}
    for source, targets in edges.items():
        for target in targets:
            pred.setdefault(target, set()).add(source)
    queue = deque(easy)
    while queue:
        for source in pred.get(queue.popleft(), set()):
            if source not in easy:
                easy.add(source); queue.append(source)
    return easy

if __name__ == "__main__":
    graph = {"Demon control": ["Hard target"], "Verifier": ["Demon control"]}
    print(sorted(closure(graph, {"Hard target"})))

